"""Build a self-contained customer segmentation dashboard HTML file from the sample CSV."""
from pathlib import Path
import csv, json

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'outputs'
with (OUT/'Mall_Customers.csv').open(newline='',encoding='utf-8-sig') as f:
    reader=csv.DictReader(f); headers=reader.fieldnames; rows=list(reader)
data={'headers':headers,'rows':rows}
html=r'''<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customer Segmentation Studio</title>
<style>
:root{--ink:#173532;--muted:#6c7d78;--line:#e4eae5;--paper:#f4f7f3;--card:#fff;--teal:#16776d;--orange:#dc8055;--shadow:0 8px 28px #1538330b}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.45 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}.shell{max-width:1420px;margin:auto;padding:32px 38px 48px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:30px}.brand{display:flex;gap:12px;align-items:center}.logo{width:42px;height:42px;border-radius:13px;background:#dceee7;color:var(--teal);display:grid;place-items:center;font-size:23px}.eyebrow{text-transform:uppercase;letter-spacing:.13em;font-size:10px;color:var(--teal);font-weight:800}.brand h1{font-size:17px;margin:1px 0}.source-pill{background:#e5f1eb;color:#2c6455;padding:8px 12px;border-radius:22px;font-size:12px;font-weight:650}.intro{display:flex;justify-content:space-between;align-items:end;margin-bottom:23px}.intro h2{font-size:31px;letter-spacing:-.04em;margin:0 0 5px}.intro p{margin:0;color:var(--muted)}.runstate{color:#397464;font-size:12px;font-weight:700}.layout{display:grid;grid-template-columns:290px 1fr;gap:20px}.card{background:var(--card);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow)}.controls{padding:21px;height:max-content;position:sticky;top:16px}.controls h3{font-size:15px;margin:0 0 18px}.field{margin:17px 0}.field label,.sub-label{display:block;color:#536762;font-size:12px;font-weight:700;margin-bottom:7px}.filebox{border:1px dashed #a8bcb4;background:#f8fbf8;border-radius:12px;padding:15px;text-align:center;color:#48625b}.filebox input{width:100%;font-size:11px;margin:8px 0}.filebox small{display:block;color:var(--muted)}select,input[type=number]{width:100%;border:1px solid var(--line);border-radius:9px;padding:10px;color:var(--ink);background:white;font:inherit}input[type=range]{width:100%;accent-color:var(--teal)}.range-row{display:flex;justify-content:space-between;align-items:center}.range-value{font-size:12px;background:#e8f3ee;padding:3px 9px;border-radius:20px;color:var(--teal);font-weight:800}.hint{font-size:11px;color:var(--muted);margin-top:6px}.button{border:0;border-radius:10px;background:var(--teal);color:white;font-weight:750;padding:11px 14px;cursor:pointer}.button:hover{background:#105f57}.button.secondary{background:white;color:var(--teal);border:1px solid #bad2c8;width:100%;margin-top:6px}.main{min-width:0}.kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:16px}.kpi{padding:17px 19px}.kpi .k-label{font-size:11px;color:var(--muted);font-weight:700}.kpi .k-value{font-size:25px;font-weight:780;letter-spacing:-.04em;margin-top:4px}.kpi .k-note{font-size:11px;color:#86948f;margin-top:2px}.charts{display:grid;grid-template-columns:1.35fr 1fr;gap:16px;margin-bottom:16px}.chart-card{padding:17px 18px;min-width:0}.card-head{display:flex;justify-content:space-between;align-items:start;margin-bottom:10px}.card-head h3{font-size:14px;margin:0}.card-head p{font-size:11px;color:var(--muted);margin:3px 0 0}.axis-selects{display:flex;gap:7px}.axis-selects select{width:auto;max-width:145px;padding:6px 8px;font-size:11px}.scatter{width:100%;height:300px;overflow:visible}.gridline{stroke:#e7ede9;stroke-width:1}.tick{font-size:10px;fill:#7d8b86}.axis-title{font-size:11px;fill:#576a64}.point{stroke:white;stroke-width:1;opacity:.82}.legend{display:flex;flex-wrap:wrap;gap:8px 14px;padding:5px 0 0;font-size:11px;color:#60736d}.legend span{display:flex;gap:6px;align-items:center}.dot{width:9px;height:9px;border-radius:50%;display:inline-block}.profiles{padding:18px;margin-bottom:16px;overflow:auto}.table-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.table-title h3{margin:0;font-size:14px}.table-title small{color:var(--muted)}table{border-collapse:collapse;width:100%;white-space:nowrap}th{text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:#74847e;font-weight:750;padding:10px 12px;border-bottom:1px solid var(--line)}td{padding:11px 12px;border-bottom:1px solid #eff2ef;font-size:12px}tr:last-child td{border-bottom:0}.tag{display:inline-block;padding:4px 9px;border-radius:20px;font-size:10px;font-weight:750;background:#edf4f0;color:#315b50}.data-card{padding:18px;overflow:auto}.data-card h3{font-size:14px;margin:0}.data-card .preview-note{font-size:11px;color:var(--muted);margin:4px 0 10px}.download{font-size:11px;padding:8px 11px}.footer{font-size:11px;color:#7a8983;margin-top:19px}.error{color:#a7412d;background:#fff2ef;border-radius:9px;padding:10px;margin-top:12px;font-size:12px;display:none}@media(max-width:900px){.shell{padding:22px 16px}.layout{grid-template-columns:1fr}.controls{position:static}.charts{grid-template-columns:1fr}.intro{display:block}.runstate{margin-top:10px}.kpis{gap:8px}.kpi{padding:13px}.kpi .k-value{font-size:21px}}@media(max-width:500px){.kpis{grid-template-columns:1fr}.source-pill{display:none}.intro h2{font-size:25px}}
</style></head><body><div class="shell">
<header class="top"><div class="brand"><div class="logo">◉</div><div><div class="eyebrow">Customer intelligence</div><h1>Segmentation Studio</h1></div></div><div class="source-pill" id="sourcePill">● Sample data loaded</div></header>
<section class="intro"><div><h2>Know your customer groups.</h2><p>Explore patterns with K-means clustering and build segments you can act on.</p></div><div class="runstate" id="runState">Analysis ready</div></section>
<div class="layout"><aside class="card controls"><h3>Set up your analysis</h3>
<div class="field"><label>Customer data (CSV)</label><div class="filebox">Choose a CSV file<input type="file" id="fileInput" accept=".csv,text/csv"><small>Use one row per customer and numeric columns for clustering.</small></div><button class="button secondary" id="resetBtn">Restore sample data</button></div>
<div class="field"><label for="kSlider">Number of segments (K)</label><div class="range-row"><span class="hint">Choose how many groups</span><span class="range-value" id="kValue">5</span></div><input id="kSlider" type="range" min="2" max="8" value="5"></div>
<div class="field"><label for="featureSelect">Features used for clustering</label><select id="featureSelect" multiple size="5" aria-label="Select clustering features"></select><div class="hint">Hold Ctrl (Windows) or ⌘ (Mac) to select multiple. Customer IDs are excluded.</div></div>
<div class="field"><label>Scatter plot axes</label><div class="axis-selects" style="display:grid;grid-template-columns:1fr 1fr"><select id="xSelect" aria-label="Horizontal axis"></select><select id="ySelect" aria-label="Vertical axis"></select></div></div>
<button class="button" id="downloadBtn" style="width:100%">↓ &nbsp;Export segmented CSV</button><div class="error" id="error"></div></aside>
<main class="main"><section class="kpis"><div class="card kpi"><div class="k-label">CUSTOMERS ANALYZED</div><div class="k-value" id="customerKpi">—</div><div class="k-note">Customer rows in this analysis</div></div><div class="card kpi"><div class="k-label">SEGMENTS FOUND</div><div class="k-value" id="segmentKpi">—</div><div class="k-note">K-means cluster count</div></div><div class="card kpi"><div class="k-label">FEATURES USED</div><div class="k-value" id="featureKpi">—</div><div class="k-note">Standardized before clustering</div></div></section>
<section class="charts"><div class="card chart-card"><div class="card-head"><div><h3>Customer map</h3><p>Each point represents one customer</p></div></div><div id="scatterWrap"></div><div class="legend" id="legend"></div></div><div class="card chart-card"><div class="card-head"><div><h3>Segment size</h3><p>Number of customers in each group</p></div></div><div id="barWrap"></div></div></section>
<section class="card profiles"><div class="table-title"><h3>Segment profiles</h3><small>Average characteristics by cluster</small></div><div id="profileWrap"></div></section>
<section class="card data-card"><div class="table-title"><div><h3>Customer assignments</h3><div class="preview-note" id="previewNote">Preview of assigned customer records</div></div><button class="button download" id="downloadBtn2">Export CSV</button></div><div id="dataWrap"></div></section>
<div class="footer">Educational sample data. Segments describe patterns in the selected fields and should be validated before business use.</div></main></div></div>
<script>
const SAMPLE=__DATA__;
let rows=SAMPLE.rows.map(r=>({...r})), headers=[...SAMPLE.headers], numeric=[], assigned=[], profiles=[], colors=['#16776d','#e18155','#5675aa','#c99b36','#875f91','#53a58f','#d16b79','#69818b'];
const $=id=>document.getElementById(id);
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function parseCSV(text){let out=[],row=[],v='',q=false;for(let i=0;i<text.length;i++){let c=text[i];if(q){if(c==='"'&&text[i+1]==='"'){v+='"';i++}else if(c==='"')q=false;else v+=c}else if(c==='"')q=true;else if(c===','){row.push(v);v=''}else if(c==='\n'){row.push(v.replace(/\r$/,''));out.push(row);row=[];v=''}else v+=c}if(v.length||row.length){row.push(v.replace(/\r$/,''));out.push(row)}return out.filter(r=>r.some(x=>x.trim()!==''))}
function identifyNumeric(){numeric=headers.filter(h=>{const values=rows.slice(0,Math.min(rows.length,100)).map(r=>Number(r[h]));return values.length&&values.every(Number.isFinite)&&!/(^id$|customer.?id|^index$|^unnamed)/i.test(h)})}
function setupSelects(){let prior=[...$('featureSelect').selectedOptions].map(o=>o.value);$('featureSelect').innerHTML=numeric.map(h=>`<option value="${esc(h)}">${esc(h)}</option>`).join('');let defaults=numeric.filter(h=>/income|spend/i.test(h)).slice(0,2);if(defaults.length<2)defaults=numeric.slice(0,Math.min(3,numeric.length));for(const o of $('featureSelect').options)o.selected=prior.includes(o.value)||(!prior.length&&defaults.includes(o.value));const fill=el=>{let old=el.value;el.innerHTML=numeric.map(h=>`<option value="${esc(h)}">${esc(h)}</option>`).join('');el.value=numeric.includes(old)?old:(numeric[0]||'')};fill($('xSelect'));fill($('ySelect'));if(numeric.length>1&&$('xSelect').value===$('ySelect').value)$('ySelect').value=numeric[1]}
function selectedFeatures(){return [...$('featureSelect').selectedOptions].map(o=>o.value)}
function kmeans(X,k){let best=null;for(let run=0;run<5;run++){let seed=231+run*71;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};let centers=[X[Math.floor(rand()*X.length)]];for(let j=1;j<k;j++){let d=X.map(x=>Math.min(...centers.map(c=>x.reduce((s,v,i)=>s+(v-c[i])**2,0))));let sum=d.reduce((a,b)=>a+b,0),pick=rand()*sum,idx=d.findIndex(v=>(pick-=v)<=0);centers.push(X[Math.max(0,idx)])}let labels=[];for(let it=0;it<150;it++){labels=X.map(x=>{let ds=centers.map(c=>x.reduce((s,v,i)=>s+(v-c[i])**2,0));return ds.indexOf(Math.min(...ds))});let next=centers.map((c,j)=>{let a=X.filter((_,i)=>labels[i]===j);return a.length?c.map((_,d)=>a.reduce((s,x)=>s+x[d],0)/a.length):X[Math.floor(rand()*X.length)]});if(next.every((c,j)=>c.every((v,d)=>Math.abs(v-centers[j][d])<1e-7))){centers=next;break}centers=next}labels=X.map(x=>{let ds=centers.map(c=>x.reduce((s,v,i)=>s+(v-c[i])**2,0));return ds.indexOf(Math.min(...ds))});let inertia=X.reduce((s,x,i)=>s+x.reduce((a,v,d)=>a+(v-centers[labels[i]][d])**2,0),0);if(!best||inertia<best.inertia)best={labels,centers,inertia}}return best}
function run(){const err=$('error');err.style.display='none';let feats=selectedFeatures();if(!numeric.length){err.textContent='No numeric fields found. Check that your CSV has numeric columns.';err.style.display='block';return}if(feats.length<2){err.textContent='Select at least two numeric features for clustering.';err.style.display='block';return}let vals=rows.map(r=>feats.map(f=>Number(r[f])));if(vals.some(r=>r.some(v=>!Number.isFinite(v)))){err.textContent='Some selected values are missing or non-numeric. Clean those rows or choose other fields.';err.style.display='block';return}let means=feats.map((_,j)=>vals.reduce((s,r)=>s+r[j],0)/vals.length),std=feats.map((_,j)=>Math.sqrt(vals.reduce((s,r)=>s+(r[j]-means[j])**2,0)/vals.length)||1),Z=vals.map(r=>r.map((v,j)=>(v-means[j])/std[j]));let k=Number($('kSlider').value),fit=kmeans(Z,k);assigned=fit.labels;let order=Array.from({length:k},(_,j)=>j).sort((a,b)=>fit.centers[a][0]-fit.centers[b][0]||fit.centers[a][1]-fit.centers[b][1]);let names={};order.forEach((j,i)=>names[j]=`Segment ${String.fromCharCode(65+i)}`);profiles=order.map(j=>{let ix=assigned.map((x,i)=>x===j?i:-1).filter(i=>i>=0);let p={name:names[j],count:ix.length,centroid:fit.centers[j],values:{}};for(const h of numeric)p.values[h]=ix.reduce((s,i)=>s+Number(rows[i][h]),0)/ix.length;return p});assigned=assigned.map(x=>names[x]);$('customerKpi').textContent=rows.length.toLocaleString();$('segmentKpi').textContent=k;$('featureKpi').textContent=feats.length;$('kValue').textContent=k;$('runState').textContent=`Updated just now · inertia ${fit.inertia.toFixed(1)}`;render(feats)}
function render(feats){let profilesHTML=`<table><thead><tr><th>Segment</th><th>Customers</th><th>Share</th>${numeric.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>`;profiles.forEach(p=>{profilesHTML+=`<tr><td><span class="tag" style="background:${colors[profiles.indexOf(p)]}18;color:${colors[profiles.indexOf(p)]}">${esc(p.name)}</span></td><td>${p.count}</td><td>${(p.count/rows.length*100).toFixed(1)}%</td>${numeric.map(h=>`<td>${Number.isInteger(p.values[h])?p.values[h].toFixed(0):p.values[h].toFixed(1)}</td>`).join('')}</tr>`});$('profileWrap').innerHTML=profilesHTML+'</tbody></table>';
let counts=profiles.map(p=>p.count),max=Math.max(...counts);$('barWrap').innerHTML=`<svg viewBox="0 0 390 300" class="scatter" role="img" aria-label="Segment sizes">${profiles.map((p,i)=>{let y=23+i*52,w=250*p.count/max;return `<text x="0" y="${y+13}" class="tick">${esc(p.name)}</text><rect x="0" y="${y+20}" width="${w}" height="19" rx="6" fill="${colors[i]}"/><text x="${w+8}" y="${y+34}" class="tick">${p.count}</text>`}).join('')}</svg>`;
let xh=$('xSelect').value,yh=$('ySelect').value,xv=rows.map(r=>+r[xh]),yv=rows.map(r=>+r[yh]),xmin=Math.min(...xv),xmax=Math.max(...xv),ymin=Math.min(...yv),ymax=Math.max(...yv);let W=540,H=300,L=55,R=15,T=14,B=42,px=x=>L+(x-xmin)/(xmax-xmin||1)*(W-L-R),py=y=>T+(ymax-y)/(ymax-ymin||1)*(H-T-B);let grid=[0,1,2,3,4].map(i=>{let y=T+i*(H-T-B)/4,val=ymax-i*(ymax-ymin)/4;return `<line class="gridline" x1="${L}" y1="${y}" x2="${W-R}" y2="${y}"/><text class="tick" x="${L-8}" y="${y+3}" text-anchor="end">${val.toFixed(0)}</text>`}).join('');let pts=rows.map((r,i)=>{let c=profiles.findIndex(p=>p.name===assigned[i]);return `<circle class="point" cx="${px(xv[i])}" cy="${py(yv[i])}" r="4.3" fill="${colors[c]}"><title>${esc(r[headers[0]]||`Customer ${i+1}`)} · ${esc(assigned[i])} · ${esc(xh)} ${xv[i]} · ${esc(yh)} ${yv[i]}</title></circle>`}).join('');$('scatterWrap').innerHTML=`<svg class="scatter" viewBox="0 0 ${W} ${H}" role="img" aria-label="Customer scatter plot">${grid}<line x1="${L}" y1="${H-B}" x2="${W-R}" y2="${H-B}" stroke="#cad6cf"/><line x1="${L}" y1="${T}" x2="${L}" y2="${H-B}" stroke="#cad6cf"/>${pts}<text class="axis-title" x="${(W+L-R)/2}" y="${H-8}" text-anchor="middle">${esc(xh)}</text><text class="axis-title" transform="translate(13 ${(H+T-B)/2}) rotate(-90)" text-anchor="middle">${esc(yh)}</text></svg>`;$('legend').innerHTML=profiles.map((p,i)=>`<span><i class="dot" style="background:${colors[i]}"></i>${esc(p.name)}</span>`).join('');$('dataWrap').innerHTML=`<table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}<th>Segment</th></tr></thead><tbody>${rows.slice(0,10).map((r,i)=>`<tr>${headers.map(h=>`<td>${esc(r[h])}</td>`).join('')}<td><span class="tag">${esc(assigned[i])}</span></td></tr>`).join('')}</tbody></table>`;$('previewNote').textContent=`Showing first ${Math.min(rows.length,10)} of ${rows.length.toLocaleString()} assigned customer rows`}
function download(){let lines=[...headers,'Segment'].join(',')+'\n'+rows.map((r,i)=>headers.map(h=>'"'+String(r[h]).replaceAll('"','""')+'"').join(',')+','+assigned[i]).join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines],{type:'text/csv'}));a.download='customer_segments.csv';a.click();URL.revokeObjectURL(a.href)}
function load(data,label){headers=data.headers;rows=data.rows;identifyNumeric();setupSelects();$('sourcePill').textContent='● '+label;run()}
$('kSlider').addEventListener('input',run);$('featureSelect').addEventListener('change',run);$('xSelect').addEventListener('change',run);$('ySelect').addEventListener('change',run);$('downloadBtn').addEventListener('click',download);$('downloadBtn2').addEventListener('click',download);$('resetBtn').addEventListener('click',()=>load(JSON.parse(JSON.stringify(SAMPLE)),'Sample data loaded'));
$('fileInput').addEventListener('change',async e=>{let f=e.target.files[0];if(!f)return;try{let parsed=parseCSV(await f.text());if(parsed.length<2)throw Error('The CSV appears empty.');let h=parsed[0].map(x=>x.trim()),rs=parsed.slice(1).map(a=>Object.fromEntries(h.map((x,i)=>[x,(a[i]||'').trim()])));load({headers:h,rows:rs},f.name)}catch(ex){$('error').textContent=ex.message;$('error').style.display='block'}});
load(JSON.parse(JSON.stringify(SAMPLE)),'Sample data loaded');
</script></body></html>'''
html=html.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('</','<\\/'))
(OUT/'customer_segmentation_app.html').write_text(html,encoding='utf-8')
print(f"Built {OUT/'customer_segmentation_app.html'} with {len(rows)} embedded sample customers")
